/bin/bash -lc "cat > /tmp/dashboard-fetch-mock.cjs <<'EOF'
const originalFetch = globalThis.fetch
let count = 0
globalThis.fetch = async function (input, init) {
  const url = typeof input === 'string' ? input : input.url
  if (url === 'https://api.example.com/dashboard') {
    count += 1
    console.log('MOCK_DASHBOARD_REQUEST', count)
    await new Promise((resolve) => setTimeout(resolve, 2000))
    return new Response(JSON.stringify({ totalRevenue: 1234, totalInvoices: 2, revenue: [{ month: 'Jan', amount: 1234 }], invoices: [{ id: '1', name: 'Acme', amount: 1234 }] }), { headers: { 'content-type': 'application/json' } })
  }
  return originalFetch(input, init)
}
EOF
NODE_OPTIONS='--require=/tmp/dashboard-fetch-mock.cjs' npm run start -- --port 3456"

/bin/bash -lc "node --input-type=module <<'EOF'
import http from 'node:http'
const started = Date.now()
const chunks = []
await new Promise((resolve, reject) => {
  http.get('http://localhost:3456/', (response) => {
    console.log('status', response.statusCode)
    response.setEncoding('utf8')
    response.on('data', (chunk) => chunks.push({ at: Date.now() - started, text: chunk }))
    response.on('end', resolve)
  }).on('error', reject)
})
const shell = chunks.find((chunk) => chunk.text.includes('Loading...'))
const data = chunks.find((chunk) => chunk.text.includes('Acme'))
console.log('shell:', shell && { afterMs: shell.at, heading: shell.text.includes('Dashboard'), sections: ['Total Revenue', 'Total Invoices', 'Revenue', 'Latest Invoices'].every((label) => shell.text.includes(label)) })
console.log('streamed data:', data && { afterMs: data.at, revenue: data.text.includes('1,234'), invoice: data.text.includes('Acme') })
if ("'!shell || !data || shell.at >= data.at) process.exitCode = 1
EOF'
